import 'fake-indexeddb/auto';
import {afterEach,describe,it,expect} from 'vitest';
import {ScenarioStore} from './store';
import {createProject,createEntity,newId,textToRichText} from '../domain/model';
import {AccountScopedSyncStore} from '../sync/adapter';
import {nativeDocuments} from '../sync/nativeBridge';
import {valueHash, type SyncSession, type SyncOperation} from '../sync/protocol';
import {ContractSyncServer} from '../sync/testing';
import {SyncOutbox} from '../sync/outbox';
import {inspectScenario} from './archive';
const stores:ScenarioStore[]=[],names=new WeakMap<ScenarioStore,string>();const account=newId();function open(fault?:()=>void){const databaseName=`rb09-${newId()}`,store=new ScenarioStore({databaseName,accountId:account,faultInjector:stage=>{if(stage==='before-commit')fault?.();}});stores.push(store);names.set(store,databaseName);return store;}function reopen(store:ScenarioStore){const databaseName=names.get(store)!;store.close();const next=new ScenarioStore({databaseName,accountId:account});names.set(next,databaseName);stores.push(next);return next;}afterEach(async()=>{for(const store of stores.splice(0))await store.deleteDatabase();});
async function seed(){const p=createProject('同期の確認'),note=createEntity(p.projectId,'note','共通元',{body:textToRichText('共通本文')});note.visibility='team';p.entities.push(note);const a=open(),b=open(),left=(await a.saveProject(p,{reason:'端末A初期'})).project,right=(await b.saveProject(p,{reason:'端末B初期'})).project,docs=nativeDocuments(left,'1'),hash=await valueHash(docs),server=new ContractSyncServer();server.seed({projectId:p.projectId,revision:'1',documents:docs,members:{[account]:'owner'}});for(const [store,project]of [[a,left],[b,right]] as const)await store.bindConfirmedProject({projectId:p.projectId,serverRevision:'1',documents:docs,contentHash:hash,localRevision:project.revision,outboxIds:(await store.listOutbox(p.projectId)).map(row=>row.operationId)});return {a,b,left,right,server,id:note.id,projectId:p.projectId};}
const session:SyncSession={accountId:account,authenticated:true,generation:newId()};
async function save(store:ScenarioStore,projectId:string,id:string,field:'name'|'body',value:string){const p=(await store.getProject(projectId))!,n=p.entities.find(n=>n.id===id)!;if(field==='name')n.name=value;else if(n.kind==='note')n.data.body=textToRichText(value);return (await store.saveProject(p,{reason:`${field}を変更`})).project;}
async function send(store:ScenarioStore,server:ContractSyncServer,projectId:string){await store.prepareSavedOperations(projectId);return new SyncOutbox(new AccountScopedSyncStore({...store,accountId:account,listPreparedOperations:store.listPreparedOperations.bind(store),listPreparedConflicts:store.listPreparedConflicts.bind(store),commitPreparedAck:store.commitPreparedAck.bind(store)}),()=>session,server).flush({accountId:account,projectId});}

describe('native prepared synchronization (contract server, not real Auth/RLS/Storage)',()=>{
 it('prepares from confirmed common base rather than the last local command, merges separate fields, persists ack and reopens the same native edition',async()=>{const f=await seed();await save(f.a,f.projectId,f.id,'name','Aの改名');expect((await send(f.a,f.server,f.projectId)).status).toBe('synced');await save(f.b,f.projectId,f.id,'body','Bの本文');const operation=await f.b.prepareSavedOperations(f.projectId);expect(operation?.baseRevision).toBe('1');expect(operation?.targets.find(target=>target.targetId===f.id)?.base?.fields.name).toBe('共通元');expect((await send(f.b,f.server,f.projectId)).status).toBe('synced');const result=(await f.b.getProject(f.projectId))!;expect(result.entities.find(n=>n.id===f.id)).toMatchObject({name:'Aの改名',data:{body:[{text:'Bの本文'}]}});expect(await f.b.listOutbox(f.projectId)).toHaveLength(0);expect(await f.b.listSyncAckEvidence(f.projectId)).toHaveLength(1);expect((await f.b.getConfirmedSyncBase(f.projectId))?.serverRevision).toBe('3');f.b=reopen(f.b);expect((await f.b.getProject(f.projectId))?.entities).toEqual(result.entities);});
 it('keeps edits made during a delayed send pending, rebases the next aggregate, and refuses a stale prepared dependency',async()=>{const f=await seed();await save(f.a,f.projectId,f.id,'name','送信する第一稿');const operation=(await f.a.prepareSavedOperations(f.projectId))!,ack=await f.server.send(operation,session);await save(f.a,f.projectId,f.id,'name','通信中の第二稿');await f.a.commitPreparedAck(f.projectId,ack);expect((await f.a.getProject(f.projectId))?.entities.find(n=>n.id===f.id)?.name).toBe('通信中の第二稿');expect(await f.a.listOutbox(f.projectId)).toHaveLength(1);const next=(await f.a.prepareSavedOperations(f.projectId))!;expect(next.operationId).not.toBe(operation.operationId);expect(next.baseRevision).toBe('2');expect(next.targets[0].base?.fields.name).toBe('送信する第一稿');expect((await send(f.a,f.server,f.projectId)).status).toBe('synced');expect(f.server.readForTest(f.projectId).documents.find(d=>d.id===f.id)?.fields.name).toBe('通信中の第二稿');});
 it('keeps the entire rejected batch and base/local/server alternatives across cold reopen, rejects changed approval, and confirms an explicit server resolution',async()=>{const f=await seed();await save(f.a,f.projectId,f.id,'name','A案');await send(f.a,f.server,f.projectId);await save(f.b,f.projectId,f.id,'name','B案');const report=await send(f.b,f.server,f.projectId);expect(report.status).toBe('conflict');f.b=reopen(f.b);const row=(await f.b.listSyncConflictAlternatives(f.projectId))[0];expect(row.conflicts[0]).toMatchObject({base:{fields:{name:'共通元'}},local:{fields:{name:'B案'}},server:{fields:{name:'A案'}}});const plan=await f.b.previewSyncResolution(f.projectId,row.operationId,{[f.id]:{strategy:'server'}});await save(f.b,f.projectId,f.id,'body','確認中の追加本文');await expect(f.b.confirmSyncResolution(plan)).rejects.toMatchObject({code:'REVISION_CHANGED'});expect(await f.b.listPreparedConflicts(f.projectId)).toHaveLength(1);const fresh=await f.b.previewSyncResolution(f.projectId,row.operationId,{[f.id]:{strategy:'server'}});await f.b.confirmSyncResolution(fresh);expect((await send(f.b,f.server,f.projectId)).status).toBe('synced');expect((await f.b.getProject(f.projectId))?.entities.find(n=>n.id===f.id)?.name).toBe('A案');expect(await f.b.listPreparedConflicts(f.projectId)).toHaveLength(0);});
 it('retains prepared/outbox/native state when local ack transaction fails and accepts only an identical retry acknowledgement',async()=>{const f=await seed();let fail=false;const faulty=open(()=>{if(fail)throw new DOMException('quota','QuotaExceededError');}),base=(await faulty.saveProject({...f.left,revision:'0',history:[]},{reason:'別端末初期'})).project,docs=nativeDocuments(base,'1');await faulty.bindConfirmedProject({projectId:f.projectId,serverRevision:'1',documents:docs,contentHash:await valueHash(docs),localRevision:base.revision,outboxIds:(await faulty.listOutbox(f.projectId)).map(row=>row.operationId)});await save(faulty,f.projectId,f.id,'name','確定待ち');const operation=(await faulty.prepareSavedOperations(f.projectId))!,server=new ContractSyncServer();server.seed({projectId:f.projectId,revision:'1',documents:docs,members:{[account]:'owner'}});const ack=await server.send(operation,session),before=await faulty.getProject(f.projectId);fail=true;await expect(faulty.commitPreparedAck(f.projectId,ack)).rejects.toThrow();expect(await faulty.getProject(f.projectId)).toEqual(before);expect(await faulty.listPreparedOperations(f.projectId)).toHaveLength(1);expect(await faulty.listOutbox(f.projectId)).toHaveLength(1);expect(await faulty.listSyncAckEvidence(f.projectId)).toHaveLength(0);fail=false;await faulty.commitPreparedAck(f.projectId,ack);await faulty.commitPreparedAck(f.projectId,ack);expect(await faulty.listOutbox(f.projectId)).toHaveLength(0);expect(await faulty.listSyncAckEvidence(f.projectId)).toHaveLength(1);await expect(faulty.commitPreparedAck(f.projectId,{...ack,serverRevision:'99'})).rejects.toMatchObject({code:'OPERATION_REUSED'});});
 it('refuses guest/account substitution, lost responses, stale membership, and changing sessions while retaining pending data',async()=>{const f=await seed();await save(f.a,f.projectId,f.id,'name','未送信');await f.a.prepareSavedOperations(f.projectId);let current={...session};const runner=new SyncOutbox(new AccountScopedSyncStore({accountId:account,listPreparedOperations:f.a.listPreparedOperations.bind(f.a),listPreparedConflicts:f.a.listPreparedConflicts.bind(f.a),commitPreparedAck:f.a.commitPreparedAck.bind(f.a)}),()=>current,{send:async(op,s)=>{const ack=await f.server.send(op,s);current={...s,generation:newId()};return ack;}});expect((await runner.flush({accountId:account,projectId:f.projectId})).status).toBe('account-changed');expect(await f.a.listPreparedOperations(f.projectId)).toHaveLength(1);f.server.setMember(f.projectId,account,null);current={...session};expect((await runner.flush({accountId:account,projectId:f.projectId})).status).toBe('forbidden');expect(await f.a.listOutbox(f.projectId)).toHaveLength(1);const guest=new ScenarioStore({databaseName:`rb09-guest-${newId()}`});stores.push(guest);await expect(guest.prepareSavedOperations(f.projectId)).rejects.toMatchObject({code:'AUTH_REQUIRED'});});
});
